/// Fleet-wide thresholds and timing knobs.
///
/// Kept in one place so SQL status rules and the alert engine stay aligned.
abstract final class FleetConstants {
  static const offlineAfter = Duration(minutes: 10);
  static const staleAfter = Duration(minutes: 10);

  static const lowBatterySoc = 20.0;
  static const criticalBatterySoc = 10.0;
  static const overheatCelsius = 45.0;

  /// GPS samples with worse accuracy than this are ignored for geofence work.
  static const maxGpsAccuracyMeters = 50.0;

  /// Consecutive samples needed before we treat a geofence transition as confirmed.
  static const geofenceConfirmSamples = 2;

  /// Gap longer than this clears any in-flight transition confirmation.
  static const geofenceGapBreak = Duration(minutes: 30);

  /// Soft retention window for raw signal rows. Older rows are compacted away.
  static const signalRetention = Duration(days: 14);

  static const undoWindow = Duration(seconds: 5);

  static const demoVehicleCount = 24;
  static const scaleVehicleCount = 500;
  static const scaleSignalRows = 2000000;
}

/// Tiny helpers for safe string interpolation into DuckDB SQL.
String sqlString(String value) => "'${value.replaceAll("'", "''")}'";

String sqlBool(bool value) => value ? 'TRUE' : 'FALSE';

String sqlNullableString(String? value) =>
    value == null ? 'NULL' : sqlString(value);

String sqlNullableNum(num? value) => value == null ? 'NULL' : '$value';

String sqlTimestamp(DateTime value) =>
    sqlString(value.toUtc().toIso8601String());

enum VehicleStatus {
  offline,
  moving,
  idle,
  stopped;

  String get label => switch (this) {
        VehicleStatus.offline => 'Offline',
        VehicleStatus.moving => 'Moving',
        VehicleStatus.idle => 'Idle',
        VehicleStatus.stopped => 'Stopped',
      };

  /// Matches the SQL CASE order from the brief: first match wins.
  static VehicleStatus resolve({
    required DateTime? lastPing,
    required double? speed,
    required bool? ignitionOn,
    required DateTime now,
    Duration offlineAfter = const Duration(minutes: 10),
  }) {
    if (lastPing == null || now.difference(lastPing) > offlineAfter) {
      return VehicleStatus.offline;
    }
    if ((speed ?? 0) > 0) return VehicleStatus.moving;
    if (ignitionOn == true) return VehicleStatus.idle;
    return VehicleStatus.stopped;
  }

  static VehicleStatus? fromSql(String? raw) {
    if (raw == null) return null;
    return switch (raw.toUpperCase()) {
      'OFFLINE' => VehicleStatus.offline,
      'MOVING' => VehicleStatus.moving,
      'IDLE' => VehicleStatus.idle,
      'STOPPED' => VehicleStatus.stopped,
      _ => null,
    };
  }

  String get sqlValue => name.toUpperCase();
}

