  final bool conditionActive;
}

import 'dart:math' as math;

import 'package:fleet_console/core/constants.dart';
import 'package:fleet_console/domain/models/geofence.dart';

/// Deterministic geofence membership from event-time location history.
///
/// Strategy (documented for the brief):
/// - **Duplicates**: identical (vehicle, eventTime, lat, lng) samples are ignored.
/// - **Late packets**: we always walk samples in event-time order, never arrival order.
/// - **GPS jitter**: require [FleetConstants.geofenceConfirmSamples] consecutive
///   samples agreeing on membership before emitting a confirmed enter/exit.
/// - **Inaccurate readings**: drop samples with accuracy worse than
///   [FleetConstants.maxGpsAccuracyMeters].
/// - **Overlaps**: among active fences containing the point, pick the smallest
///   radius; ties go to the newest `createdAt`.
/// - **Missing intervals**: a gap > [FleetConstants.geofenceGapBreak] resets the
///   confirmation streak (no phantom transitions across long offline stretches).
/// - **Geofence edits**: callers should re-run this over retained history after
///   an edit; we never invent transitions for time we did not observe.
class GeofenceEngine {
  const GeofenceEngine();

  List<ProposedTransition> process({
    required String vehicleId,
    required List<LocationSample> samples,
    required List<Geofence> activeGeofences,
    String? startingGeofenceId,
  }) {
    if (samples.isEmpty || activeGeofences.isEmpty) return const [];

    final ordered = [...samples]..sort((a, b) => a.eventTime.compareTo(b.eventTime));
    final deduped = <LocationSample>[];
    final seen = <String>{};
    for (final sample in ordered) {
      final key =
          '${sample.eventTime.toIso8601String()}|${sample.lat}|${sample.lng}';
      if (seen.add(key)) deduped.add(sample);
    }

    String? current = startingGeofenceId;
    String? pendingTarget;
    var streak = 0;
    DateTime? lastAcceptedAt;
    final out = <ProposedTransition>[];

    for (final sample in deduped) {
      if (sample.accuracyMeters != null &&
          sample.accuracyMeters! > FleetConstants.maxGpsAccuracyMeters) {
        continue;
      }

      if (lastAcceptedAt != null &&
          sample.eventTime.difference(lastAcceptedAt) >
              FleetConstants.geofenceGapBreak) {
        pendingTarget = null;
        streak = 0;
      }
      lastAcceptedAt = sample.eventTime;

      final containing = _pickContaining(sample, activeGeofences);
      final target = containing?.id;

      if (target == current) {
        pendingTarget = null;
        streak = 0;
        continue;
      }

      if (target == pendingTarget) {
        streak += 1;
      } else {
        pendingTarget = target;
        streak = 1;
      }

      if (streak < FleetConstants.geofenceConfirmSamples) continue;

      if (current != null) {
        out.add(
          ProposedTransition(
            vehicleId: vehicleId,
            geofenceId: current,
            type: GeofenceTransitionType.exit,
            eventTime: sample.eventTime,
          ),
        );
      }
      if (target != null) {
        out.add(
          ProposedTransition(
            vehicleId: vehicleId,
            geofenceId: target,
            type: GeofenceTransitionType.enter,
            eventTime: sample.eventTime,
          ),
        );
      }

      current = target;
      pendingTarget = null;
      streak = 0;
    }

    return out;
  }

  Geofence? containingFence(LocationSample sample, List<Geofence> fences) =>
      _pickContaining(sample, fences);

  Geofence? _pickContaining(LocationSample sample, List<Geofence> fences) {
    final hits = <Geofence>[];
    for (final fence in fences) {
      if (!fence.active) continue;
      final d = haversineMeters(sample.lat, sample.lng, fence.lat, fence.lng);
      if (d <= fence.radiusMeters) hits.add(fence);
    }
    if (hits.isEmpty) return null;
    hits.sort((a, b) {
      final byRadius = a.radiusMeters.compareTo(b.radiusMeters);
      if (byRadius != 0) return byRadius;
      return b.createdAt.compareTo(a.createdAt);
    });
    return hits.first;
  }
}

class LocationSample {
  const LocationSample({
    required this.lat,
    required this.lng,
    required this.eventTime,
    this.accuracyMeters,
  });

  final double lat;
  final double lng;
  final DateTime eventTime;
  final double? accuracyMeters;
}

class ProposedTransition {
  const ProposedTransition({
    required this.vehicleId,
    required this.geofenceId,
    required this.type,
    required this.eventTime,
  });

  final String vehicleId;
  final String geofenceId;
  final GeofenceTransitionType type;
  final DateTime eventTime;

  /// Stable id so replaying the same transition is a no-op.
  String get idempotencyKey =>
      '$vehicleId|${geofenceId}|${type.name}|${eventTime.toUtc().toIso8601String()}';
}

double haversineMeters(
  double lat1,
  double lng1,
  double lat2,
  double lng2,
) {
  const earthRadius = 6371000.0;
  final dLat = _rad(lat2 - lat1);
  final dLng = _rad(lng2 - lng1);
  final a = math.sin(dLat / 2) * math.sin(dLat / 2) +
      math.cos(_rad(lat1)) *
          math.cos(_rad(lat2)) *
          math.sin(dLng / 2) *
          math.sin(dLng / 2);
  final c = 2 * math.atan2(math.sqrt(a), math.sqrt(1 - a));
  return earthRadius * c;
}

double _rad(double deg) => deg * math.pi / 180.0;

import 'package:fleet_console/domain/models/geofence.dart';
import 'package:fleet_console/domain/models/trip.dart';
import 'package:fleet_console/domain/services/geofence_engine.dart';

/// Builds trips from confirmed geofence transitions.
///
/// Confirmed exit starts a trip. The next confirmed enter completes it.
/// Returning to the origin fence is valid. One active trip per vehicle.
/// Replay is idempotent via transition keys; late packets may revise the
/// destination / end time of an open or recently completed trip when the
/// event time falls inside the trip window — but never create a second trip
/// for the same exit.
class TripEngine {
  const TripEngine();

  List<TripMutation> apply({
    required String vehicleId,
    required List<ProposedTransition> confirmed,
    Trip? activeTrip,
  }) {
    final mutations = <TripMutation>[];
    var open = activeTrip;

    final ordered = [...confirmed]
      ..sort((a, b) => a.eventTime.compareTo(b.eventTime));

    for (final t in ordered) {
      if (!t.confirmedLike) continue;

      if (t.type == GeofenceTransitionType.exit) {
        if (open != null && open.isActive) {
          // Already on a trip — ignore nested exits until we enter somewhere.
          continue;
        }
        mutations.add(
          TripMutation.start(
            vehicleId: vehicleId,
            originGeofenceId: t.geofenceId,
            startedAt: t.eventTime,
            sourceKey: t.idempotencyKey,
          ),
        );
        open = Trip(
          id: 'pending',
          vehicleId: vehicleId,
          originGeofenceId: t.geofenceId,
          startedAt: t.eventTime,
          status: TripStatus.inProgress,
        );
      } else if (t.type == GeofenceTransitionType.enter) {
        if (open == null || !open.isActive) continue;
        if (t.eventTime.isBefore(open.startedAt)) continue;

        mutations.add(
          TripMutation.complete(
            vehicleId: vehicleId,
            destinationGeofenceId: t.geofenceId,
            endedAt: t.eventTime,
            sourceKey: t.idempotencyKey,
          ),
        );
        open = null;
      }
    }

    return mutations;
  }
}

extension on ProposedTransition {
  // Proposed transitions from GeofenceEngine are already "confirmed".
  bool get confirmedLike => true;
}

sealed class TripMutation {
  const TripMutation();

  factory TripMutation.start({
    required String vehicleId,
    required String originGeofenceId,
    required DateTime startedAt,
    required String sourceKey,
  }) = TripStart;

  factory TripMutation.complete({
    required String vehicleId,
    required String destinationGeofenceId,
    required DateTime endedAt,
    required String sourceKey,
  }) = TripComplete;
}

class TripStart extends TripMutation {
  const TripStart({
    required this.vehicleId,
    required this.originGeofenceId,
    required this.startedAt,
    required this.sourceKey,
  });

  final String vehicleId;
  final String originGeofenceId;
  final DateTime startedAt;
  final String sourceKey;
}

class TripComplete extends TripMutation {
  const TripComplete({
    required this.vehicleId,
    required this.destinationGeofenceId,
    required this.endedAt,
    required this.sourceKey,
  });

  final String vehicleId;
  final String destinationGeofenceId;
  final DateTime endedAt;
  final String sourceKey;
}

import 'package:fleet_console/core/constants.dart';
import 'package:fleet_console/domain/models/signal.dart';

class SignalVerdictResolver {
  const SignalVerdictResolver();

  SignalVerdict? verdict({
    required double? value,
    required DateTime? eventTime,
    required SignalKind kind,
    required DateTime now,
    required bool alertCondition,
  }) {
    if (value == null && eventTime == null) return null;
    if (eventTime == null) return null;
    if (now.difference(eventTime) > FleetConstants.staleAfter) {
      return SignalVerdict.stale;
    }
    if (alertCondition) return SignalVerdict.alert;
    return SignalVerdict.normal;
  }

  bool isAlertCondition(SignalKind kind, double? value) {
    if (value == null) return false;
    return switch (kind) {
      SignalKind.soc => value < FleetConstants.lowBatterySoc,
      SignalKind.batteryTemp => value > FleetConstants.overheatCelsius,
      _ => false,
    };
  }
}

import 'dart:io';

import 'package:dart_duckdb/dart_duckdb.dart';
import 'package:fleet_console/data/database/schema.dart';
import 'package:path/path.dart' as p;
import 'package:path_provider/path_provider.dart';

/// Owns the on-disk DuckDB file. Everything the app "knows" lives here.
class FleetDatabase {
  FleetDatabase._(this._db, this._conn, this.path);

  final Database _db;
  final Connection _conn;
  final String path;

  Connection get connection => _conn;

  static Future<FleetDatabase> open({String? overridePath}) async {
    final path = overridePath ?? await _defaultPath();
    final parent = Directory(p.dirname(path));
    if (!parent.existsSync()) {
      await parent.create(recursive: true);
    }

    final db = await duckdb.open(path);
    final conn = await duckdb.connect(db);
    final fleet = FleetDatabase._(db, conn, path);
    await fleet._migrate();
    return fleet;
  }

  /// In-memory handle for unit tests.
  static Future<FleetDatabase> openInMemory() async {
    final db = await duckdb.open(':memory:');
    final conn = await duckdb.connect(db);
    final fleet = FleetDatabase._(db, conn, ':memory:');
    await fleet._migrate();
    return fleet;
  }

  static Future<String> _defaultPath() async {
    final dir = await getApplicationSupportDirectory();
    return p.join(dir.path, 'fleet_console.duckdb');
  }

  Future<void> _migrate() async {
    for (final stmt in FleetSchema.createStatements) {
      await _conn.execute(stmt);
    }
  }

  Future<void> execute(String sql) => _conn.execute(sql);

  Future<ResultSet> query(String sql) => _conn.query(sql);

  Future<List<List<Object?>>> fetchAll(String sql) async {
    final result = await _conn.query(sql);
    return result.fetchAll();
  }

  Future<Object?> fetchScalar(String sql) async {
    final rows = await fetchAll(sql);
    if (rows.isEmpty || rows.first.isEmpty) return null;
    return rows.first.first;
  }

  Future<void> dispose() async {
    await _conn.dispose();
    await _db.dispose();
  }
}

