class VehicleRepository {
  VehicleRepository(this._db, {DateTime Function()? clock})
      : _clock = clock ?? DateTime.now;

  final FleetDatabase _db;
  final DateTime Function() _clock;
  final _uuid = const Uuid();

  Future<void> upsertVehicle({
    required String id,
    required String regNumber,
    required String model,
  }) async {
    await _db.execute('''
      INSERT INTO vehicles (id, reg_number, model)
      VALUES (${sqlString(id)}, ${sqlString(regNumber)}, ${sqlString(model)})
      ON CONFLICT (id) DO UPDATE SET
        reg_number = excluded.reg_number,
        model = excluded.model
    ''');
  }

  Future<int> vehicleCount() async {
    final n = await _db.fetchScalar('SELECT COUNT(*) FROM vehicles');
    return (n as num?)?.toInt() ?? 0;
  }

  Future<FleetFilterCounts> filterCounts() async {
    final now = _clock().toUtc();
    final base = FleetSchema.fleetListSql(
      nowIso: now.toIso8601String(),
      offlineMinutes: FleetConstants.offlineAfter.inMinutes,
    );
    final rows = await _db.fetchAll('''
      $base
      SELECT
        COUNT(*) AS all_count,
        SUM(CASE WHEN status = 'MOVING' THEN 1 ELSE 0 END) AS moving,
        SUM(CASE WHEN status = 'IDLE' THEN 1 ELSE 0 END) AS idle,
        SUM(CASE WHEN status = 'STOPPED' THEN 1 ELSE 0 END) AS stopped,
        SUM(CASE WHEN status = 'OFFLINE' THEN 1 ELSE 0 END) AS offline
      FROM ranked
    ''');
    if (rows.isEmpty) return const FleetFilterCounts();
    final r = rows.first;
    return FleetFilterCounts(
      all: (r[0] as num?)?.toInt() ?? 0,
      moving: (r[1] as num?)?.toInt() ?? 0,
      idle: (r[2] as num?)?.toInt() ?? 0,
      stopped: (r[3] as num?)?.toInt() ?? 0,
      offline: (r[4] as num?)?.toInt() ?? 0,
    );
  }

  Future<List<VehicleListItem>> list({VehicleStatus? filter}) async {
    final now = _clock().toUtc();
    final base = FleetSchema.fleetListSql(
      nowIso: now.toIso8601String(),
      offlineMinutes: FleetConstants.offlineAfter.inMinutes,
    );
    final where = filter == null
        ? ''
        : 'WHERE status = ${sqlString(filter.sqlValue)}';
    final rows = await _db.fetchAll('''
      $base
      SELECT id, reg_number, model, status, soc, range_km, speed, ignition,
             last_ping, active_alert_count, geofence_name
      FROM ranked
      $where
      ORDER BY reg_number
    ''');

    return rows.map((r) {
      return VehicleListItem(
        id: r[0]! as String,
        regNumber: r[1]! as String,
        model: r[2]! as String,
        status: VehicleStatus.fromSql(r[3] as String?) ?? VehicleStatus.offline,
        soc: (r[4] as num?)?.toDouble(),
        rangeKm: (r[5] as num?)?.toDouble(),
        speed: (r[6] as num?)?.toDouble(),
        ignitionOn: r[7] == null ? null : ((r[7] as num) >= 1),
        lastPing: _asDateTime(r[8]),
        activeAlertCount: (r[9] as num?)?.toInt() ?? 0,
        currentGeofenceName: r[10] as String?,
      );
    }).toList();
  }

  Future<Vehicle?> get(String id) async {
    final rows = await _db.fetchAll('''
      SELECT id, reg_number, model FROM vehicles WHERE id = ${sqlString(id)}
    ''');
    if (rows.isEmpty) return null;
    final r = rows.first;
    return Vehicle(
      id: r[0]! as String,
      regNumber: r[1]! as String,
      model: r[2]! as String,
    );
  }

  String newId() => _uuid.v4();

  DateTime? _asDateTime(Object? value) {
    if (value == null) return null;
    if (value is DateTime) return value.toUtc();
    return DateTime.tryParse(value.toString())?.toUtc();
  }
}

import 'package:fleet_console/core/constants.dart';
import 'package:fleet_console/core/sql.dart';
import 'package:fleet_console/data/database/fleet_database.dart';
import 'package:fleet_console/domain/models/signal.dart';
import 'package:fleet_console/domain/services/signal_verdict.dart';
import 'package:uuid/uuid.dart';

class TelemetryRepository {
  TelemetryRepository(this._db, {DateTime Function()? clock})
      : _clock = clock ?? DateTime.now;

  final FleetDatabase _db;
  final DateTime Function() _clock;
  final _uuid = const Uuid();
  final _verdicts = const SignalVerdictResolver();

  Future<void> ingestPacket({
    required String vehicleId,
    required DateTime eventTime,
    required Map<SignalKind, double> values,
    DateTime? ingestedAt,
  }) async {
    final ingested = (ingestedAt ?? _clock()).toUtc();
    final event = eventTime.toUtc();

    // Always stamp last_ping from the packet's event time.
    final payload = Map<SignalKind, double>.from(values);
    // last_ping is stored as the event_time; value unused.
    final buffer = StringBuffer();
    buffer.writeln('BEGIN TRANSACTION;');

    void addRow(SignalKind kind, double? value) {
      final id = _uuid.v4();
      buffer.writeln('''
        INSERT INTO signals (id, vehicle_id, signal, value, event_time, ingested_at)
        VALUES (
          ${sqlString(id)},
          ${sqlString(vehicleId)},
          ${sqlString(kind.storageKey)},
          ${sqlNullableNum(value)},
          ${sqlTimestamp(event)},
          ${sqlTimestamp(ingested)}
        );
      ''');
    }

    for (final entry in payload.entries) {
      addRow(entry.key, entry.value);
    }
    addRow(SignalKind.lastPing, 1);

    buffer.writeln('COMMIT;');
    await _db.execute(buffer.toString());
  }

  Future<void> ingestMany(List<SignalInsert> rows) async {
    if (rows.isEmpty) return;
    // Chunk to keep statements manageable.
    const chunk = 500;
    for (var i = 0; i < rows.length; i += chunk) {
      final slice = rows.sublist(i, i + chunk > rows.length ? rows.length : i + chunk);
      final buf = StringBuffer('BEGIN TRANSACTION;\n');
      for (final row in slice) {
        buf.writeln('''
          INSERT INTO signals (id, vehicle_id, signal, value, event_time, ingested_at)
          VALUES (
            ${sqlString(row.id)},
            ${sqlString(row.vehicleId)},
            ${sqlString(row.signal.storageKey)},
            ${sqlNullableNum(row.value)},
            ${sqlTimestamp(row.eventTime)},
            ${sqlTimestamp(row.ingestedAt)}
          );
        ''');
      }
      buf.writeln('COMMIT;');
      await _db.execute(buf.toString());
    }
  }

  Future<List<SignalReading>> readingsForVehicle(String vehicleId) async {
    final now = _clock().toUtc();
    final kinds = [
      SignalKind.soc,
      SignalKind.rangeKm,
      SignalKind.speed,
      SignalKind.batteryTemp,
      SignalKind.odometer,
      SignalKind.lastPing,
    ];

    final readings = <SignalReading>[];
    for (final kind in kinds) {
      final rows = await _db.fetchAll('''
        SELECT value, event_time
        FROM signals
        WHERE vehicle_id = ${sqlString(vehicleId)}
          AND signal = ${sqlString(kind.storageKey)}
        ORDER BY event_time DESC
        LIMIT 1
      ''');

      if (rows.isEmpty) {
        readings.add(SignalReading(kind: kind));
        continue;
      }

      final value = (rows.first[0] as num?)?.toDouble();
      final at = _asDateTime(rows.first[1]);
      final alert = _verdicts.isAlertCondition(kind, value);
      readings.add(
        SignalReading(
          kind: kind,
          value: kind == SignalKind.lastPing ? null : value,
          eventTime: at,
          verdict: _verdicts.verdict(
            value: value,
            eventTime: at,
            kind: kind,
            now: now,
            alertCondition: alert,
          ),
        ),
      );
    }
    return readings;
  }

  Future<List<SocHistoryPoint>> socHistory(
    String vehicleId, {
    Duration window = FleetConstants.signalRetention,
  }) async {
    final since = _clock().toUtc().subtract(window);
    final rows = await _db.fetchAll('''
      SELECT event_time, value
      FROM signals
      WHERE vehicle_id = ${sqlString(vehicleId)}
        AND signal = 'soc'
        AND event_time >= ${sqlTimestamp(since)}
        AND value IS NOT NULL
      ORDER BY event_time ASC
    ''');

    return rows
        .map(
          (r) => SocHistoryPoint(
            at: _asDateTime(r[0])!,
            soc: (r[1] as num).toDouble(),
          ),
        )
        .toList();
  }

  Future<Map<SignalKind, ({double? value, DateTime eventTime})>> latestMap(
    String vehicleId,
  ) async {
    final rows = await _db.fetchAll('''
      SELECT signal, value, event_time
      FROM (
        SELECT signal, value, event_time,
               ROW_NUMBER() OVER (PARTITION BY signal ORDER BY event_time DESC) rn
        FROM signals
        WHERE vehicle_id = ${sqlString(vehicleId)}
      )
      WHERE rn = 1
    ''');

    final map = <SignalKind, ({double? value, DateTime eventTime})>{};
    for (final r in rows) {
      final kind = SignalKind.fromStorageKey(r[0]! as String);
      if (kind == null) continue;
      final at = _asDateTime(r[2]);
      if (at == null) continue;
      map[kind] = (value: (r[1] as num?)?.toDouble(), eventTime: at);
    }
    return map;
  }

  Future<List<LocationPoint>> locationHistory(
    String vehicleId, {
    Duration window = const Duration(hours: 24),
  }) async {
    final since = _clock().toUtc().subtract(window);
    final rows = await _db.fetchAll('''
      WITH lat_rows AS (
        SELECT event_time, value AS lat
        FROM signals
        WHERE vehicle_id = ${sqlString(vehicleId)}
          AND signal = 'lat'
          AND event_time >= ${sqlTimestamp(since)}
      ),
      lng_rows AS (
        SELECT event_time, value AS lng
        FROM signals
        WHERE vehicle_id = ${sqlString(vehicleId)}
          AND signal = 'lng'
          AND event_time >= ${sqlTimestamp(since)}
      ),
      acc_rows AS (
        SELECT event_time, value AS accuracy
        FROM signals
        WHERE vehicle_id = ${sqlString(vehicleId)}
          AND signal = 'gps_accuracy'
          AND event_time >= ${sqlTimestamp(since)}
      )
      SELECT l.event_time, l.lat, g.lng, a.accuracy
      FROM lat_rows l
      JOIN lng_rows g ON g.event_time = l.event_time
      LEFT JOIN acc_rows a ON a.event_time = l.event_time
      ORDER BY l.event_time ASC
    ''');

    return rows
        .map(
          (r) => LocationPoint(
            eventTime: _asDateTime(r[0])!,
            lat: (r[1] as num).toDouble(),
            lng: (r[2] as num).toDouble(),
            accuracyMeters: (r[3] as num?)?.toDouble(),
          ),
        )
        .toList();
  }

  Future<int> compactOldSignals() async {
    final cutoff = _clock().toUtc().subtract(FleetConstants.signalRetention);
    final before = await _db.fetchScalar('SELECT COUNT(*) FROM signals');
    await _db.execute('''
      DELETE FROM signals
      WHERE event_time < ${sqlTimestamp(cutoff)}
        AND signal NOT IN ('last_ping')
    ''');
    // Keep one last_ping even if old — fleet status needs it.
    final after = await _db.fetchScalar('SELECT COUNT(*) FROM signals');
    return ((before as num?)?.toInt() ?? 0) - ((after as num?)?.toInt() ?? 0);
  }

  Future<int> signalCount() async {
    final n = await _db.fetchScalar('SELECT COUNT(*) FROM signals');
    return (n as num?)?.toInt() ?? 0;
  }

  DateTime? _asDateTime(Object? value) {
    if (value == null) return null;
    if (value is DateTime) return value.toUtc();
    return DateTime.tryParse(value.toString())?.toUtc();
  }
}

class SignalInsert {
  SignalInsert({
    required this.id,
    required this.vehicleId,
    required this.signal,
    required this.value,
    required this.eventTime,
    required this.ingestedAt,
  });

  final String id;
  final String vehicleId;
  final SignalKind signal;
  final double? value;
  final DateTime eventTime;
  final DateTime ingestedAt;
}

class LocationPoint {
  const LocationPoint({
    required this.lat,
    required this.lng,
    required this.eventTime,
    this.accuracyMeters,
  });

  final double lat;
  final double lng;
  final DateTime eventTime;
  final double? accuracyMeters;
}

import 'package:fleet_console/core/sql.dart';
import 'package:fleet_console/data/database/fleet_database.dart';
import 'package:fleet_console/domain/models/alert.dart';
import 'package:fleet_console/domain/services/alert_engine.dart';
import 'package:uuid/uuid.dart';

class AlertRepository {
  AlertRepository(this._db, {DateTime Function()? clock})
      : _clock = clock ?? DateTime.now;

  final FleetDatabase _db;
  final DateTime Function() _clock;
  final _uuid = const Uuid();
  final _engine = const AlertEngine();

  Future<List<FleetAlert>> activeForVehicle(String vehicleId) async {
    final rows = await _db.fetchAll('''
      SELECT id, vehicle_id, kind, severity, message, triggered_at,
             resolved_at, dismissed_at, dismiss_reason
      FROM alerts
      WHERE vehicle_id = ${sqlString(vehicleId)}
        AND resolved_at IS NULL
        AND dismissed_at IS NULL
      ORDER BY triggered_at DESC
    ''');
    return rows.map(_map).toList();
  }

  Future<List<FleetAlert>> activeAll() async {
    final rows = await _db.fetchAll('''
      SELECT id, vehicle_id, kind, severity, message, triggered_at,
             resolved_at, dismissed_at, dismiss_reason
      FROM alerts
      WHERE resolved_at IS NULL AND dismissed_at IS NULL
      ORDER BY
        CASE severity WHEN 'critical' THEN 0 ELSE 1 END,
        triggered_at DESC
    ''');
    return rows.map(_map).toList();
  }

  Future<FleetAlert?> getById(String id) async {
    final rows = await _db.fetchAll('''
      SELECT id, vehicle_id, kind, severity, message, triggered_at,
             resolved_at, dismissed_at, dismiss_reason
      FROM alerts
      WHERE id = ${sqlString(id)}
    ''');
    if (rows.isEmpty) return null;
    return _map(rows.first);
  }

  /// Applies engine intents: open/update active alerts, or resolve when clear.
  Future<void> applyIntents(List<AlertIntent> intents) async {
    final now = _clock().toUtc();
    for (final intent in intents) {
      final existing = await _findOpen(intent.vehicleId, intent.kind);

      if (!intent.conditionActive) {
        if (existing != null) {
          await _db.execute('''
            UPDATE alerts
            SET resolved_at = ${sqlTimestamp(now)}
            WHERE id = ${sqlString(existing.id)}
              AND resolved_at IS NULL
              AND dismissed_at IS NULL
          ''');
        }
        continue;
      }

      if (existing == null) {
        final id = _uuid.v4();
        await _db.execute('''
          INSERT INTO alerts (
            id, vehicle_id, kind, severity, message, triggered_at,
            resolved_at, dismissed_at, dismiss_reason
          ) VALUES (
            ${sqlString(id)},
            ${sqlString(intent.vehicleId)},
            ${sqlString(intent.kind.storageKey)},
            ${sqlString(intent.severity.name)},
            ${sqlString(intent.message)},
            ${sqlTimestamp(now)},
            NULL, NULL, NULL
          )
        ''');
      } else if (existing.severity != intent.severity ||
          existing.message != intent.message) {
        // Escalate / refresh message on the same alert row.
        await _db.execute('''
          UPDATE alerts
          SET severity = ${sqlString(intent.severity.name)},
              message = ${sqlString(intent.message)}
          WHERE id = ${sqlString(existing.id)}
        ''');
      }
    }
  }

  Future<void> evaluateVehicle(
    String vehicleId,
    Map<SignalKindSnapshotKey, SignalSnapshot> latest,
  ) async {
    final intents = _engine.evaluate(
      vehicleId: vehicleId,
      latest: {
        for (final e in latest.entries) e.key.kind: e.value,
      },
      now: _clock().toUtc(),
    );
    await applyIntents(intents);
  }

  Future<void> dismiss({
    required String alertId,
    required String reason,
  }) async {
    final now = _clock().toUtc();
    await _db.execute('''
      UPDATE alerts
      SET dismissed_at = ${sqlTimestamp(now)},
          dismiss_reason = ${sqlString(reason)}
      WHERE id = ${sqlString(alertId)}
        AND dismissed_at IS NULL
        AND resolved_at IS NULL
    ''');
  }

  Future<void> undoDismiss(String alertId) async {
    await _db.execute('''
      UPDATE alerts
      SET dismissed_at = NULL,
          dismiss_reason = NULL
      WHERE id = ${sqlString(alertId)}
    ''');
  }

  Future<FleetAlert?> _findOpen(String vehicleId, AlertKind kind) async {
    final rows = await _db.fetchAll('''
      SELECT id, vehicle_id, kind, severity, message, triggered_at,
             resolved_at, dismissed_at, dismiss_reason
      FROM alerts
      WHERE vehicle_id = ${sqlString(vehicleId)}
        AND kind = ${sqlString(kind.storageKey)}
        AND resolved_at IS NULL
        AND dismissed_at IS NULL
      ORDER BY triggered_at DESC
      LIMIT 1
    ''');
    if (rows.isEmpty) return null;
    return _map(rows.first);
  }

  FleetAlert _map(List<Object?> r) {
    return FleetAlert(
      id: r[0]! as String,
      vehicleId: r[1]! as String,
      kind: AlertKind.fromStorage(r[2]! as String)!,
      severity: (r[3]! as String) == 'critical'
          ? AlertSeverity.critical
          : AlertSeverity.warning,
      message: r[4]! as String,
      triggeredAt: _asDateTime(r[5])!,
      resolvedAt: _asDateTime(r[6]),
      dismissedAt: _asDateTime(r[7]),
      dismissReason: r[8] as String?,
    );
  }

  DateTime? _asDateTime(Object? value) {
    if (value == null) return null;
    if (value is DateTime) return value.toUtc();
    return DateTime.tryParse(value.toString())?.toUtc();
  }
}

/// Thin key so we can pass SignalKind without importing signal.dart cycles oddly.
class SignalKindSnapshotKey {
  const SignalKindSnapshotKey(this.kind);
  final dynamic kind;
}

// Re-export friendly evaluate helper used by providers.
extension AlertRepoEval on AlertRepository {
  Future<void> evaluateFromLatest(
    String vehicleId,
    Map<dynamic, SignalSnapshot> latest,
  ) async {
    await applyIntents(
      _engine.evaluate(
        vehicleId: vehicleId,
        latest: Map.from(latest),
        now: _clock().toUtc(),
      ),
    );
  }
}

