import 'package:fleet_console/domain/services/geofence_engine.dart';
import 'package:uuid/uuid.dart';

class GeofenceRepository {
  GeofenceRepository(this._db, {DateTime Function()? clock})
      : _clock = clock ?? DateTime.now;

  final FleetDatabase _db;
  final DateTime Function() _clock;
  final _uuid = const Uuid();
  final _engine = const GeofenceEngine();

  Future<List<Geofence>> listAll({bool activeOnly = false}) async {
    final where = activeOnly ? 'WHERE active = TRUE' : '';
    final rows = await _db.fetchAll('''
      SELECT id, name, lat, lng, radius_meters, active, created_at, deactivated_at
      FROM geofences
      $where
      ORDER BY name
    ''');
    return rows.map(_map).toList();
  }

  Future<List<GeofenceWithCount>> listWithCounts() async {
    final rows = await _db.fetchAll('''
      SELECT g.id, g.name, g.lat, g.lng, g.radius_meters, g.active,
             g.created_at, g.deactivated_at,
             COALESCE(c.cnt, 0) AS vehicle_count
      FROM geofences g
      LEFT JOIN (
        SELECT geofence_id, COUNT(*) AS cnt
        FROM vehicle_geofence
        WHERE geofence_id IS NOT NULL
        GROUP BY geofence_id
      ) c ON c.geofence_id = g.id
      ORDER BY g.active DESC, g.name
    ''');

    return rows
        .map(
          (r) => GeofenceWithCount(
            geofence: _map(r),
            vehicleCount: (r[8] as num?)?.toInt() ?? 0,
          ),
        )
        .toList();
  }

  Future<Geofence?> get(String id) async {
    final rows = await _db.fetchAll('''
      SELECT id, name, lat, lng, radius_meters, active, created_at, deactivated_at
      FROM geofences WHERE id = ${sqlString(id)}
    ''');
    if (rows.isEmpty) return null;
    return _map(rows.first);
  }

  Future<String> create({
    required String name,
    required double lat,
    required double lng,
    required double radiusMeters,
  }) async {
    final id = _uuid.v4();
    final now = _clock().toUtc();
    await _db.execute('''
      INSERT INTO geofences (
        id, name, lat, lng, radius_meters, active, created_at, deactivated_at
      ) VALUES (
        ${sqlString(id)},
        ${sqlString(name)},
        $lat, $lng, $radiusMeters,
        TRUE,
        ${sqlTimestamp(now)},
        NULL
      )
    ''');
    return id;
  }

  Future<void> update(Geofence fence) async {
    await _db.execute('''
      UPDATE geofences SET
        name = ${sqlString(fence.name)},
        lat = ${fence.lat},
        lng = ${fence.lng},
        radius_meters = ${fence.radiusMeters},
        active = ${sqlBool(fence.active)},
        deactivated_at = ${fence.deactivatedAt == null ? 'NULL' : sqlTimestamp(fence.deactivatedAt!)}
      WHERE id = ${sqlString(fence.id)}
    ''');
  }

  Future<void> deactivate(String id) async {
    final now = _clock().toUtc();
    await _db.execute('''
      UPDATE geofences
      SET active = FALSE, deactivated_at = ${sqlTimestamp(now)}
      WHERE id = ${sqlString(id)}
    ''');
  }

  Future<String?> currentGeofenceId(String vehicleId) async {
    final v = await _db.fetchScalar('''
      SELECT geofence_id FROM vehicle_geofence
      WHERE vehicle_id = ${sqlString(vehicleId)}
    ''');
    return v as String?;
  }

  Future<void> setCurrentGeofence(String vehicleId, String? geofenceId) async {
    await _db.execute('''
      INSERT INTO vehicle_geofence (vehicle_id, geofence_id)
      VALUES (${sqlString(vehicleId)}, ${sqlNullableString(geofenceId)})
      ON CONFLICT (vehicle_id) DO UPDATE SET geofence_id = excluded.geofence_id
    ''');
  }

  /// Replays location history through the engine and persists confirmed transitions.
  Future<List<ProposedTransition>> recomputeVehicle({
    required String vehicleId,
    required List<LocationSample> samples,
  }) async {
    final fences = await listAll(activeOnly: true);
    final starting = await currentGeofenceId(vehicleId);
    final proposed = _engine.process(
      vehicleId: vehicleId,
      samples: samples,
      activeGeofences: fences,
      startingGeofenceId: starting,
    );

    for (final t in proposed) {
      await _insertTransition(t);
    }

    if (samples.isNotEmpty) {
      final last = [...samples]..sort((a, b) => a.eventTime.compareTo(b.eventTime));
      final membership = _engine.containingFence(last.last, fences);
      await setCurrentGeofence(vehicleId, membership?.id);
    }

    return proposed;
  }

  Future<void> _insertTransition(ProposedTransition t) async {
    // Idempotent: same key → ignore.
    final existing = await _db.fetchScalar('''
      SELECT id FROM geofence_transitions WHERE id = ${sqlString(t.idempotencyKey)}
    ''');
    if (existing != null) return;

    await _db.execute('''
      INSERT INTO geofence_transitions (
        id, vehicle_id, geofence_id, type, event_time, confirmed
      ) VALUES (
        ${sqlString(t.idempotencyKey)},
        ${sqlString(t.vehicleId)},
        ${sqlString(t.geofenceId)},
        ${sqlString(t.type.name)},
        ${sqlTimestamp(t.eventTime)},
        TRUE
      )
    ''');
  }

  Future<List<ProposedTransition>> confirmedTransitions(
    String vehicleId, {
    DateTime? since,
  }) async {
    final sinceClause = since == null
        ? ''
        : 'AND event_time >= ${sqlTimestamp(since.toUtc())}';
    final rows = await _db.fetchAll('''
      SELECT id, vehicle_id, geofence_id, type, event_time
      FROM geofence_transitions
      WHERE vehicle_id = ${sqlString(vehicleId)}
        AND confirmed = TRUE
        $sinceClause
      ORDER BY event_time ASC
    ''');

    return rows
        .map(
          (r) => ProposedTransition(
            vehicleId: r[1]! as String,
            geofenceId: r[2]! as String,
            type: (r[3]! as String) == 'enter'
                ? GeofenceTransitionType.enter
                : GeofenceTransitionType.exit,
            eventTime: _asDateTime(r[4])!,
          ),
        )
        .toList();
  }

  Geofence _map(List<Object?> r) {
    return Geofence(
      id: r[0]! as String,
      name: r[1]! as String,
      lat: (r[2] as num).toDouble(),
      lng: (r[3] as num).toDouble(),
      radiusMeters: (r[4] as num).toDouble(),
      active: r[5] == true || r[5] == 1,
      createdAt: _asDateTime(r[6])!,
      deactivatedAt: _asDateTime(r[7]),
    );
  }

  DateTime? _asDateTime(Object? value) {
    if (value == null) return null;
    if (value is DateTime) return value.toUtc();
    return DateTime.tryParse(value.toString())?.toUtc();
  }
}

import 'package:fleet_console/core/sql.dart';
import 'package:fleet_console/data/database/fleet_database.dart';
import 'package:fleet_console/domain/models/trip.dart';
import 'package:fleet_console/domain/services/geofence_engine.dart';
import 'package:fleet_console/domain/services/trip_engine.dart';
import 'package:uuid/uuid.dart';

class TripRepository {
  TripRepository(this._db, {DateTime Function()? clock})
      : _clock = clock ?? DateTime.now;

  final FleetDatabase _db;
  final DateTime Function() _clock;
  final _uuid = const Uuid();
  final _engine = const TripEngine();

  Future<List<Trip>> listForVehicle(String vehicleId) async {
    final rows = await _db.fetchAll('''
      SELECT t.id, t.vehicle_id, t.origin_geofence_id, t.destination_geofence_id,
             t.started_at, t.ended_at, t.status,
             o.name AS origin_name, d.name AS destination_name
      FROM trips t
      LEFT JOIN geofences o ON o.id = t.origin_geofence_id
      LEFT JOIN geofences d ON d.id = t.destination_geofence_id
      WHERE t.vehicle_id = ${sqlString(vehicleId)}
      ORDER BY t.started_at DESC
    ''');
    return rows.map(_map).toList();
  }

  Future<List<Trip>> listRecent({int limit = 50}) async {
    final rows = await _db.fetchAll('''
      SELECT t.id, t.vehicle_id, t.origin_geofence_id, t.destination_geofence_id,
             t.started_at, t.ended_at, t.status,
             o.name AS origin_name, d.name AS destination_name
      FROM trips t
      LEFT JOIN geofences o ON o.id = t.origin_geofence_id
      LEFT JOIN geofences d ON d.id = t.destination_geofence_id
      ORDER BY t.started_at DESC
      LIMIT $limit
    ''');
    return rows.map(_map).toList();
  }

  Future<Trip?> activeForVehicle(String vehicleId) async {
    final rows = await _db.fetchAll('''
      SELECT t.id, t.vehicle_id, t.origin_geofence_id, t.destination_geofence_id,
             t.started_at, t.ended_at, t.status,
             o.name AS origin_name, d.name AS destination_name
      FROM trips t
      LEFT JOIN geofences o ON o.id = t.origin_geofence_id
      LEFT JOIN geofences d ON d.id = t.destination_geofence_id
      WHERE t.vehicle_id = ${sqlString(vehicleId)}
        AND t.status = 'inProgress'
      ORDER BY t.started_at DESC
      LIMIT 1
    ''');
    if (rows.isEmpty) return null;
    return _map(rows.first);
  }

  Future<void> applyTransitions({
    required String vehicleId,
    required List<ProposedTransition> confirmed,
  }) async {
    final active = await activeForVehicle(vehicleId);
    final mutations = _engine.apply(
      vehicleId: vehicleId,
      confirmed: confirmed,
      activeTrip: active,
    );

    for (final m in mutations) {
      switch (m) {
        case TripStart(:final originGeofenceId, :final startedAt, :final sourceKey):
          final exists = await _db.fetchScalar('''
            SELECT id FROM trips WHERE source_start_key = ${sqlString(sourceKey)}
          ''');
          if (exists != null) continue;
          // Still only one active trip.
          final open = await activeForVehicle(vehicleId);
          if (open != null) continue;

          await _db.execute('''
            INSERT INTO trips (
              id, vehicle_id, origin_geofence_id, destination_geofence_id,
              started_at, ended_at, status, source_start_key, source_end_key
            ) VALUES (
              ${sqlString(_uuid.v4())},
              ${sqlString(vehicleId)},
              ${sqlString(originGeofenceId)},
              NULL,
              ${sqlTimestamp(startedAt)},
              NULL,
              'inProgress',
              ${sqlString(sourceKey)},
              NULL
            )
          ''');
        case TripComplete(
            :final destinationGeofenceId,
            :final endedAt,
            :final sourceKey,
          ):
          final endTaken = await _db.fetchScalar('''
            SELECT id FROM trips WHERE source_end_key = ${sqlString(sourceKey)}
          ''');
          if (endTaken != null) continue;

          final open = await activeForVehicle(vehicleId);
          if (open == null) continue;

          await _db.execute('''
            UPDATE trips SET
              destination_geofence_id = ${sqlString(destinationGeofenceId)},
              ended_at = ${sqlTimestamp(endedAt)},
              status = 'completed',
              source_end_key = ${sqlString(sourceKey)}
            WHERE id = ${sqlString(open.id)}
          ''');
      }
    }
  }

  Trip _map(List<Object?> r) {
    return Trip(
      id: r[0]! as String,
      vehicleId: r[1]! as String,
      originGeofenceId: r[2]! as String,
      destinationGeofenceId: r[3] as String?,
      startedAt: _asDateTime(r[4])!,
      endedAt: _asDateTime(r[5]),
      status: (r[6]! as String) == 'completed'
          ? TripStatus.completed
          : TripStatus.inProgress,
      originName: r[7] as String?,
      destinationName: r[8] as String?,
    );
  }

  DateTime? _asDateTime(Object? value) {
    if (value == null) return null;
    if (value is DateTime) return value.toUtc();
    return DateTime.tryParse(value.toString())?.toUtc();
  }
}

import 'dart:math';

import 'package:fleet_console/core/constants.dart';
import 'package:fleet_console/core/sql.dart';
import 'package:fleet_console/data/database/fleet_database.dart';
import 'package:fleet_console/data/repositories/alert_repository.dart';
import 'package:fleet_console/data/repositories/geofence_repository.dart';
import 'package:fleet_console/data/repositories/telemetry_repository.dart';
import 'package:fleet_console/data/repositories/trip_repository.dart';
import 'package:fleet_console/data/repositories/vehicle_repository.dart';
import 'package:fleet_console/domain/models/signal.dart';
import 'package:fleet_console/domain/services/alert_engine.dart';
import 'package:fleet_console/domain/services/geofence_engine.dart';
import 'package:uuid/uuid.dart';

/// Seeds a small, realistic demo fleet the first time the DB is empty.
class DemoSeed {
  DemoSeed({
    required FleetDatabase db,
    DateTime Function()? clock,
  })  : _db = db,
        _clock = clock ?? DateTime.now,
        vehicles = VehicleRepository(db, clock: clock),
        telemetry = TelemetryRepository(db, clock: clock),
        alerts = AlertRepository(db, clock: clock),
        geofences = GeofenceRepository(db, clock: clock),
        trips = TripRepository(db, clock: clock);

  final FleetDatabase _db;
  final DateTime Function() _clock;
  final VehicleRepository vehicles;
  final TelemetryRepository telemetry;
  final AlertRepository alerts;
  final GeofenceRepository geofences;
  final TripRepository trips;
  final _uuid = const Uuid();

  Future<bool> needsSeed() async {
    final flag = await _db.fetchScalar(
      "SELECT value FROM meta WHERE key = 'seeded'",
    );
    if (flag == '1') return false;
    return (await vehicles.vehicleCount()) == 0;
  }

  Future<void> runIfNeeded() async {
    if (!await needsSeed()) return;
    await run();
  }

  Future<void> run() async {
    final now = _clock().toUtc();
    final rng = Random(42);

    final depotId = await geofences.create(
      name: 'Depot North',
      lat: 12.9716,
      lng: 77.5946,
      radiusMeters: 400,
    );
    final hubId = await geofences.create(
      name: 'City Hub',
      lat: 12.9352,
      lng: 77.6245,
      radiusMeters: 350,
    );
    final yardId = await geofences.create(
      name: 'South Yard',
      lat: 12.9081,
      lng: 77.6512,
      radiusMeters: 500,
    );

    // Keep a deactivated fence around for trip history demos.
    final oldId = await geofences.create(
      name: 'Old Staging (retired)',
      lat: 12.9600,
      lng: 77.5800,
      radiusMeters: 300,
    );
    await geofences.deactivate(oldId);

    final fenceCenters = [
      (depotId, 12.9716, 77.5946),
      (hubId, 12.9352, 77.6245),
      (yardId, 12.9081, 77.6512),
    ];

    const models = [
      'Volvo FH Electric',
      'Tesla Semi',
      'BYD 8TT',
      'Mercedes eActros',
      'Scania 40R',
    ];

    for (var i = 0; i < FleetConstants.demoVehicleCount; i++) {
      final id = 'veh-${(i + 1).toString().padLeft(3, '0')}';
      final reg = 'KA01-EV-${(1000 + i).toString()}';
      final model = models[i % models.length];
      await vehicles.upsertVehicle(id: id, regNumber: reg, model: model);

      final statusRoll = i % 5;
      final ageMinutes = switch (statusRoll) {
        0 => 45, // offline
        1 => 2, // moving
        2 => 3, // idle
        3 => 4, // stopped
        _ => 1,
      };

      final eventTime = now.subtract(Duration(minutes: ageMinutes));
      final soc = switch (i % 7) {
        0 => 8.0 + rng.nextDouble() * 2, // critical
        1 => 15.0 + rng.nextDouble() * 3, // warning
        _ => 35.0 + rng.nextDouble() * 55,
      };
      final temp = i % 11 == 0 ? 47.0 + rng.nextDouble() * 3 : 28.0 + rng.nextDouble() * 10;
      final speed = statusRoll == 1 ? 20.0 + rng.nextDouble() * 40 : 0.0;
      final ignition = statusRoll == 3 ? 0.0 : (statusRoll == 0 ? 0.0 : 1.0);

      final fence = fenceCenters[i % fenceCenters.length];
      // Moving trucks sit slightly outside their "home" fence.
      final lat = fence.$2 + (statusRoll == 1 ? 0.01 : 0.0005 * rng.nextDouble());
      final lng = fence.$3 + (statusRoll == 1 ? 0.008 : 0.0005 * rng.nextDouble());

      await telemetry.ingestPacket(
        vehicleId: id,
        eventTime: eventTime,
        values: {
          SignalKind.soc: soc,
          SignalKind.rangeKm: soc * 3.2,
          SignalKind.speed: speed,
          SignalKind.batteryTemp: temp,
          SignalKind.odometer: 12000 + i * 337.0 + rng.nextDouble() * 50,
          SignalKind.ignition: ignition,
          SignalKind.lat: lat,
          SignalKind.lng: lng,
          SignalKind.gpsAccuracy: 8 + rng.nextDouble() * 10,
        },
      );

      // A short trail so geofence confirmation has two samples.
      final earlier = eventTime.subtract(const Duration(minutes: 2));
      await telemetry.ingestPacket(
        vehicleId: id,
        eventTime: earlier,
        values: {
          SignalKind.soc: soc + 1,
          SignalKind.rangeKm: (soc + 1) * 3.2,
          SignalKind.speed: speed,
          SignalKind.batteryTemp: temp,
          SignalKind.odometer: 12000 + i * 337.0,
          SignalKind.ignition: ignition,
          SignalKind.lat: lat - 0.0002,
          SignalKind.lng: lng - 0.0001,
          SignalKind.gpsAccuracy: 10,
        },
      );

      final latest = await telemetry.latestMap(id);
      await alerts.evaluateFromLatest(
        id,
        {
          for (final e in latest.entries)
            e.key: SignalSnapshot(value: e.value.value, eventTime: e.value.eventTime),
        },
      );

      final history = await telemetry.locationHistory(id);
      final samples = history
          .map(
            (p) => LocationSample(
              lat: p.lat,
              lng: p.lng,
              eventTime: p.eventTime,
              accuracyMeters: p.accuracyMeters,
            ),
          )
          .toList();
      final transitions = await geofences.recomputeVehicle(
        vehicleId: id,
        samples: samples,
      );
      await trips.applyTransitions(vehicleId: id, confirmed: transitions);

      // Seed one completed trip for a handful of trucks.
      if (i % 6 == 0) {
        final startKey = '$id|seed-start|$i';
        final endKey = '$id|seed-end|$i';
        await _db.execute('''
          INSERT INTO trips (
            id, vehicle_id, origin_geofence_id, destination_geofence_id,
            started_at, ended_at, status, source_start_key, source_end_key
          ) VALUES (
            ${sqlString(_uuid.v4())},
            ${sqlString(id)},
            ${sqlString(depotId)},
            ${sqlString(hubId)},
            ${sqlTimestamp(now.subtract(Duration(hours: 5 + i % 3)))},
            ${sqlTimestamp(now.subtract(Duration(hours: 3 + i % 2)))},
            'completed',
            ${sqlString(startKey)},
            ${sqlString(endKey)}
          )
        ''');
      }
    }

    await _db.execute('''
      INSERT INTO meta (key, value) VALUES ('seeded', '1')
      ON CONFLICT (key) DO UPDATE SET value = '1'
    ''');
  }
}

import 'dart:math';

import 'package:fleet_console/core/constants.dart';
import 'package:fleet_console/data/database/fleet_database.dart';
import 'package:fleet_console/data/repositories/telemetry_repository.dart';
import 'package:fleet_console/data/repositories/vehicle_repository.dart';
import 'package:fleet_console/domain/models/signal.dart';
import 'package:uuid/uuid.dart';

/// Debug/scale action: 500 vehicles and ~2M signal rows.
class ScaleBackfill {
  ScaleBackfill(this._db, {DateTime Function()? clock})
      : _clock = clock ?? DateTime.now,
        _vehicles = VehicleRepository(_db, clock: clock),
        _telemetry = TelemetryRepository(_db, clock: clock);

  final FleetDatabase _db;
  final DateTime Function() _clock;
  final VehicleRepository _vehicles;
  final TelemetryRepository _telemetry;
  final _uuid = const Uuid();

  Future<ScaleBackfillResult> run({
    void Function(double progress, String label)? onProgress,
  }) async {
    final started = DateTime.now();
    final now = _clock().toUtc();
    final rng = Random(7);
    const models = ['Volvo FH Electric', 'Tesla Semi', 'BYD 8TT', 'eActros'];

    onProgress?.call(0.02, 'Creating vehicles…');
    for (var i = 0; i < FleetConstants.scaleVehicleCount; i++) {
      final id = 'scale-${(i + 1).toString().padLeft(4, '0')}';
      await _vehicles.upsertVehicle(
        id: id,
        regNumber: 'SC-${(10000 + i)}',
        model: models[i % models.length],
      );
      if (i % 50 == 0) {
        onProgress?.call(0.02 + (i / FleetConstants.scaleVehicleCount) * 0.08, 'Vehicles $i');
      }
    }

    // ~2M rows across vehicles. Each packet writes several signal rows.
    const signalsPerPacket = 6;
    final packetsNeeded =
        (FleetConstants.scaleSignalRows / signalsPerPacket).ceil();
    final packetsPerVehicle =
        (packetsNeeded / FleetConstants.scaleVehicleCount).ceil();

    onProgress?.call(0.12, 'Writing signal history…');
    var written = 0;
    final batch = <SignalInsert>[];

    for (var v = 0; v < FleetConstants.scaleVehicleCount; v++) {
      final vehicleId = 'scale-${(v + 1).toString().padLeft(4, '0')}';
      for (var p = 0; p < packetsPerVehicle; p++) {
        final event = now.subtract(Duration(minutes: p * 3 + (v % 5)));
        final ingested = event.add(Duration(seconds: rng.nextInt(40)));
        final soc = 20 + rng.nextDouble() * 70;

        void add(SignalKind kind, double? value) {
          batch.add(
            SignalInsert(
              id: _uuid.v4(),
              vehicleId: vehicleId,
              signal: kind,
              value: value,
              eventTime: event,
              ingestedAt: ingested,
            ),
          );
        }

        add(SignalKind.soc, soc);
        add(SignalKind.rangeKm, soc * 3);
        add(SignalKind.speed, rng.nextDouble() * 60);
        add(SignalKind.batteryTemp, 25 + rng.nextDouble() * 15);
        add(SignalKind.odometer, 10000 + v * 10.0 + p);
        add(SignalKind.lastPing, 1);

        if (batch.length >= 2000) {
          written += batch.length;
          await _telemetry.ingestMany(batch);
          batch.clear();
          onProgress?.call(
            0.12 + (written / FleetConstants.scaleSignalRows).clamp(0, 1) * 0.85,
            'Signals ~$written',
          );
        }
      }
    }

    if (batch.isNotEmpty) {
      written += batch.length;
      await _telemetry.ingestMany(batch);
    }

    await _db.execute('''
      INSERT INTO meta (key, value) VALUES ('scale_backfill', '1')
      ON CONFLICT (key) DO UPDATE SET value = '1'
    ''');

    final elapsed = DateTime.now().difference(started);
    final signalCount = await _telemetry.signalCount();
    onProgress?.call(1, 'Done');

    return ScaleBackfillResult(
      vehicles: FleetConstants.scaleVehicleCount,
      signalRows: signalCount,
      elapsed: elapsed,
    );
  }
}

class ScaleBackfillResult {
  const ScaleBackfillResult({
    required this.vehicles,
    required this.signalRows,
    required this.elapsed,
  });

  final int vehicles;
  final int signalRows;
  final Duration elapsed;
}

import 'package:fleet_console/data/repositories/alert_repository.dart';
import 'package:fleet_console/data/repositories/geofence_repository.dart';
import 'package:fleet_console/data/repositories/telemetry_repository.dart';
import 'package:fleet_console/data/repositories/trip_repository.dart';
import 'package:fleet_console/domain/models/signal.dart';
import 'package:fleet_console/domain/services/alert_engine.dart';
import 'package:fleet_console/domain/services/geofence_engine.dart';

/// Single write path: telemetry → DuckDB, then derive alerts / fences / trips.
class TelemetryIngestor {
  TelemetryIngestor({
    required this.telemetry,
    required this.alerts,
    required this.geofences,
    required this.trips,
  });

  final TelemetryRepository telemetry;
  final AlertRepository alerts;
  final GeofenceRepository geofences;
  final TripRepository trips;

  Future<void> ingest({
    required String vehicleId,
    required DateTime eventTime,
    required Map<SignalKind, double> values,
  }) async {
    await telemetry.ingestPacket(
      vehicleId: vehicleId,
      eventTime: eventTime,
      values: values,
    );

    final latest = await telemetry.latestMap(vehicleId);
    await alerts.evaluateFromLatest(
      vehicleId,
      {
        for (final e in latest.entries)
          e.key: SignalSnapshot(
            value: e.value.value,
            eventTime: e.value.eventTime,
          ),
      },
    );

    final hasLocation =
        values.containsKey(SignalKind.lat) && values.containsKey(SignalKind.lng);
    if (hasLocation) {
      final history = await telemetry.locationHistory(vehicleId);
      final samples = history
          .map(
            (p) => LocationSample(
              lat: p.lat,
              lng: p.lng,
              eventTime: p.eventTime,
              accuracyMeters: p.accuracyMeters,
            ),
          )
          .toList();
      final transitions = await geofences.recomputeVehicle(
        vehicleId: vehicleId,
        samples: samples,
      );
      await trips.applyTransitions(
        vehicleId: vehicleId,
        confirmed: transitions,
      );
    }
  }
}

import 'package:fleet_console/data/database/fleet_database.dart';
import 'package:fleet_console/data/repositories/alert_repository.dart';
import 'package:fleet_console/data/repositories/geofence_repository.dart';
