/// Overrides wired once DuckDB is ready — keeps repos out of every FutureProvider.
List<Override> repositoryOverrides(FleetDatabase db) {
  final vehicles = VehicleRepository(db);
  final telemetry = TelemetryRepository(db);
  final alerts = AlertRepository(db);
  final geofences = GeofenceRepository(db);
  final trips = TripRepository(db);
  final ingestor = TelemetryIngestor(
    telemetry: telemetry,
    alerts: alerts,
    geofences: geofences,
    trips: trips,
  );

  return [
    vehicleRepositoryProvider.overrideWithValue(vehicles),
    telemetryRepositoryProvider.overrideWithValue(telemetry),
    alertRepositoryProvider.overrideWithValue(alerts),
    geofenceRepositoryProvider.overrideWithValue(geofences),
    tripRepositoryProvider.overrideWithValue(trips),
    telemetryIngestorProvider.overrideWithValue(ingestor),
  ];
}

