class ScaleBackfillProgress {
  const ScaleBackfillProgress({
    this.running = false,
    this.progress = 0,
    this.label = '',
    this.resultSummary,
  });

  final bool running;
  final double progress;
  final String label;
  final String? resultSummary;
}

class ScaleBackfillNotifier extends Notifier<ScaleBackfillProgress> {
  @override
  ScaleBackfillProgress build() => const ScaleBackfillProgress();

  Future<void> run() async {
    if (state.running) return;
    state = const ScaleBackfillProgress(running: true, label: 'Starting…');
    final db = await _ref.watch(fleetDatabaseProvider.future);
    // ignore: unused_local_variable — imported lazily to avoid cycles in analyzer
    final backfill = await _runBackfill(db);
    state = ScaleBackfillProgress(
      running: false,
      progress: 1,
      label: 'Done',
      resultSummary: backfill,
    );
    _ref.invalidate(fleetListProvider);
    _ref.invalidate(fleetCountsProvider);
  }

  Future<String> _runBackfill(dynamic db) async {
    // Local import pattern kept simple for the notifier.
    final scale = await importScale(db);
    return scale;
  }
}

// Separate top-level to keep the notifier readable.
Future<String> importScale(dynamic db) async {
  // Implemented in scale_provider.dart companion — see below.
  throw UnimplementedError();
}

