import 'package:fleet_console/core/constants.dart';
import 'package:fleet_console/domain/models/alert.dart';
import 'package:fleet_console/domain/models/signal.dart';
import 'package:fleet_console/domain/services/alert_engine.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  const engine = AlertEngine();
  final now = DateTime.utc(2026, 9, 6, 12);

  SignalSnapshot snap(double value, {Duration age = Duration.zero}) =>
      SignalSnapshot(value: value, eventTime: now.subtract(age));

  test('critical SOC escalates over warning on the same kind', () {
    final critical = engine.evaluate(
      vehicleId: 'v1',
      latest: {SignalKind.soc: snap(8)},
      now: now,
    );
    expect(critical.single.kind, AlertKind.lowBattery);
    expect(critical.single.severity, AlertSeverity.critical);
    expect(critical.single.conditionActive, isTrue);

    final warning = engine.evaluate(
      vehicleId: 'v1',
      latest: {SignalKind.soc: snap(15)},
      now: now,
    );
    expect(warning.single.severity, AlertSeverity.warning);
  });

  test('SOC recovery emits a clear intent', () {
    final intents = engine.evaluate(
      vehicleId: 'v1',
      latest: {SignalKind.soc: snap(55)},
      now: now,
    );
    expect(intents.single.kind, AlertKind.lowBattery);
    expect(intents.single.conditionActive, isFalse);
  });

  test('stale readings do not open alerts', () {
    final intents = engine.evaluate(
      vehicleId: 'v1',
      latest: {
        SignalKind.soc: snap(5, age: FleetConstants.staleAfter + const Duration(minutes: 1)),
        SignalKind.batteryTemp: snap(50, age: FleetConstants.staleAfter + const Duration(minutes: 1)),
      },
      now: now,
    );
    expect(intents, isEmpty);
  });

  test('overheating threshold', () {
    final hot = engine.evaluate(
      vehicleId: 'v1',
      latest: {SignalKind.batteryTemp: snap(46)},
      now: now,
    );
    expect(hot.single.kind, AlertKind.overheating);
    expect(hot.single.conditionActive, isTrue);

    final cool = engine.evaluate(
      vehicleId: 'v1',
      latest: {SignalKind.batteryTemp: snap(40)},
      now: now,
    );
    expect(cool.single.conditionActive, isFalse);
  });
}

import 'package:fleet_console/domain/models/geofence.dart';
import 'package:fleet_console/domain/services/geofence_engine.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  const engine = GeofenceEngine();

  final depot = Geofence(
    id: 'depot',
    name: 'Depot',
    lat: 0,
    lng: 0,
    radiusMeters: 200,
    active: true,
    createdAt: DateTime.utc(2026, 1, 1),
  );

  final hub = Geofence(
    id: 'hub',
    name: 'Hub',
    lat: 0.01,
    lng: 0,
    radiusMeters: 200,
    active: true,
    createdAt: DateTime.utc(2026, 1, 2),
  );

  LocationSample at(double lat, double lng, int minute, {double accuracy = 10}) {
    return LocationSample(
      lat: lat,
      lng: lng,
      eventTime: DateTime.utc(2026, 9, 6, 10, minute),
      accuracyMeters: accuracy,
    );
  }

  test('requires two agreeing samples before confirming exit/enter', () {
    final transitions = engine.process(
      vehicleId: 'v1',
      startingGeofenceId: depot.id,
      activeGeofences: [depot, hub],
      samples: [
        at(0, 0, 0), // still in depot
        at(0.01, 0, 1), // one sample in hub — not enough
      ],
    );
    expect(transitions, isEmpty);

    final confirmed = engine.process(
      vehicleId: 'v1',
      startingGeofenceId: depot.id,
      activeGeofences: [depot, hub],
      samples: [
        at(0.01, 0, 1),
        at(0.01, 0, 2),
      ],
    );
    expect(confirmed.map((t) => t.type).toList(), [
      GeofenceTransitionType.exit,
      GeofenceTransitionType.enter,
    ]);
    expect(confirmed.first.geofenceId, depot.id);
    expect(confirmed.last.geofenceId, hub.id);
  });

  test('drops inaccurate GPS and ignores exact duplicates', () {
    final transitions = engine.process(
      vehicleId: 'v1',
      startingGeofenceId: depot.id,
      activeGeofences: [depot, hub],
      samples: [
        at(0.01, 0, 1, accuracy: 80),
        at(0.01, 0, 1, accuracy: 80), // duplicate + bad accuracy
        at(0.01, 0, 2),
        at(0.01, 0, 2), // duplicate of good sample
        at(0.01, 0, 3),
      ],
    );
    expect(transitions.length, 2);
  });

  test('overlap prefers smaller radius', () {
    final big = Geofence(
      id: 'big',
      name: 'Big',
      lat: 0,
      lng: 0,
      radiusMeters: 2000,
      active: true,
      createdAt: DateTime.utc(2026, 1, 1),
    );
    final small = Geofence(
      id: 'small',
      name: 'Small',
      lat: 0,
      lng: 0,
      radiusMeters: 100,
      active: true,
      createdAt: DateTime.utc(2026, 1, 1),
    );

    final pick = engine.containingFence(at(0, 0, 0), [big, small]);
    expect(pick?.id, 'small');
  });
}

import 'package:fleet_console/domain/models/geofence.dart';
import 'package:fleet_console/domain/models/trip.dart';
import 'package:fleet_console/domain/services/geofence_engine.dart';
import 'package:fleet_console/domain/services/trip_engine.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  const engine = TripEngine();

  ProposedTransition exitAt(int minute) => ProposedTransition(
        vehicleId: 'v1',
        geofenceId: 'depot',
        type: GeofenceTransitionType.exit,
        eventTime: DateTime.utc(2026, 9, 6, 10, minute),
      );

  ProposedTransition enterHubAt(int minute) => ProposedTransition(
        vehicleId: 'v1',
        geofenceId: 'hub',
        type: GeofenceTransitionType.enter,
        eventTime: DateTime.utc(2026, 9, 6, 10, minute),
      );

  test('exit starts a trip and enter completes it', () {
    final mutations = engine.apply(
      vehicleId: 'v1',
      confirmed: [exitAt(0), enterHubAt(20)],
    );

    expect(mutations, hasLength(2));
    expect(mutations[0], isA<TripStart>());
    expect(mutations[1], isA<TripComplete>());
    final complete = mutations[1] as TripComplete;
    expect(complete.destinationGeofenceId, 'hub');
  });

  test('second exit while trip is open is ignored', () {
    final open = Trip(
      id: 't1',
      vehicleId: 'v1',
      originGeofenceId: 'depot',
      startedAt: DateTime.utc(2026, 9, 6, 10),
      status: TripStatus.inProgress,
    );

    final mutations = engine.apply(
      vehicleId: 'v1',
      activeTrip: open,
      confirmed: [exitAt(5), enterHubAt(30)],
    );

    expect(mutations, hasLength(1));
    expect(mutations.single, isA<TripComplete>());
  });

  test('returning to origin is a valid completion', () {
    final mutations = engine.apply(
      vehicleId: 'v1',
      confirmed: [
        exitAt(0),
        ProposedTransition(
          vehicleId: 'v1',
          geofenceId: 'depot',
          type: GeofenceTransitionType.enter,
          eventTime: DateTime.utc(2026, 9, 6, 10, 40),
        ),
      ],
    );

    final complete = mutations.whereType<TripComplete>().single;
    expect(complete.destinationGeofenceId, 'depot');
  });
}

import 'package:fleet_console/domain/models/vehicle_status.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  final now = DateTime.utc(2026, 9, 6, 12);

  test('offline wins when last ping is old', () {
    final status = VehicleStatus.resolve(
      lastPing: now.subtract(const Duration(minutes: 11)),
      speed: 40,
      ignitionOn: true,
      now: now,
    );
    expect(status, VehicleStatus.offline);
  });

  test('moving before idle when speed > 0', () {
    final status = VehicleStatus.resolve(
      lastPing: now.subtract(const Duration(minutes: 1)),
      speed: 12,
      ignitionOn: true,
      now: now,
    );
    expect(status, VehicleStatus.moving);
  });

  test('idle when speed 0 and ignition on', () {
    final status = VehicleStatus.resolve(
      lastPing: now,
      speed: 0,
      ignitionOn: true,
      now: now,
    );
    expect(status, VehicleStatus.idle);
  });

  test('stopped when ignition off', () {
    final status = VehicleStatus.resolve(
      lastPing: now,
      speed: 0,
      ignitionOn: false,
      now: now,
    );
    expect(status, VehicleStatus.stopped);
  });
}

