import 'package:fleet_console/domain/models/vehicle_status.dart';
import 'package:fleet_console/domain/services/alert_engine.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  test('duckdb fleet list + alert round trip', () async {
    late FleetDatabase db;
    try {
      db = await FleetDatabase.openInMemory();
    } catch (e) {
      // CI / hosts without the native DuckDB binary.
      // ignore: avoid_print
      print('Skipping DuckDB integration test: $e');
      return;
    }

    addTearDown(db.dispose);

    final vehicles = VehicleRepository(db, clock: () => DateTime.utc(2026, 9, 6, 12));
    final telemetry = TelemetryRepository(db, clock: () => DateTime.utc(2026, 9, 6, 12));
    final alerts = AlertRepository(db, clock: () => DateTime.utc(2026, 9, 6, 12));

    await vehicles.upsertVehicle(
      id: 'v1',
      regNumber: 'KA01-EV-1',
      model: 'Test Truck',
    );

    await telemetry.ingestPacket(
      vehicleId: 'v1',
      eventTime: DateTime.utc(2026, 9, 6, 11, 55),
      values: {
        SignalKind.soc: 9,
        SignalKind.rangeKm: 30,
        SignalKind.speed: 12,
        SignalKind.batteryTemp: 30,
        SignalKind.odometer: 1000,
        SignalKind.ignition: 1,
      },
    );

    final latest = await telemetry.latestMap('v1');
    await alerts.evaluateFromLatest(
      'v1',
      {
        for (final e in latest.entries)
          e.key: SignalSnapshot(
            value: e.value.value,
            eventTime: e.value.eventTime,
          ),
      },
    );

    final list = await vehicles.list();
    expect(list, hasLength(1));
    expect(list.single.status, VehicleStatus.moving);
    expect(list.single.hasAlert, isTrue);

    final open = await alerts.activeForVehicle('v1');
    expect(open.single.severity.name, 'critical');

    await alerts.dismiss(alertId: open.single.id, reason: 'I am on it');
    expect(await alerts.activeForVehicle('v1'), isEmpty);

    await alerts.undoDismiss(open.single.id);
    expect(await alerts.activeForVehicle('v1'), hasLength(1));
  });
}

